abhinav_29_31 = {
    'hi': '।।9.29--9.31।। श्री अभिनवगुप्त कहते हैं: परमेश्वर सर्वभूतों में सम हैं, न कोई प्रिय है न द्वेष्य; किंतु जो भक्ति से भगवान् का भजन करते हैं, वे भगवान् में हैं और भगवान् उनमें। अति दुराचारी भी अनन्य भक्ति से शीघ्र धर्मात्मा बनकर नित्य शान्ति को प्राप्त होता है और भगवद्भक्त कभी विनष्ट नहीं होता।',
    'en': '9.29--9.31 Sri Abhinavagupta states: The Lord is equal to all beings, without hatred or partiality; yet those who worship Him with devotion abide in Him, and He in them. Even a deeply wicked person worshipping with undivided devotion swiftly becomes virtuous and attains eternal peace, and the Lord"s devotee never perishes.',
    'be': '৯.২৯--৯.৩১ শ্রী অভিনবগুপ্ত বলেছেন: পরমেশ্বর সর্বভূতে সম, না কেউ প্রিয় না দ্বেষ্য; কিন্তু যারা ভক্তিতে ভগবানের ভজন করে, তারা ভগবানে আছে এবং ভগবান তাদের মধ্যে। অতি দুরাচারীও অনন্য ভক্তিতে শীঘ্র ধর্মাচ্চা হয়ে নিত্য শান্তি প্রাপ্ত হয় এবং ভগবদ্ভক্ত কখনো বিনষ্ট হয় না।',
    'ka': '೯.೨೯--೯.೩೧ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಪರಮೇಶ್ವರನು ಸರ್ವಭೂತಗಳಲ್ಲಿ ಸಮನಾಗಿದ್ದಾನೆ, ಯಾರೂ ಪ್ರಿಯನಲ್ಲ, ದ್ವೇಷ್ಯನಲ್ಲ; ಆದರೆ ಭಕ್ತಿಯಿಂದ ಭಗವಂತನನ್ನು ಭಜಿಸುವವರು ಭಗವಂತನಲ್ಲಿದ್ದಾರೆ ಹಾಗೂ ಭಗವಂತನು ಅವರಲ್ಲಿದ್ದಾನೆ. ಅತಿ ದುರಾಚಾರಿಯೂ ಅನನ್ಯ ಭಕ್ತಿಯಿಂದ ಶೀಘ್ರವೇ ಧರ್ಮಾತ್ಮನಾಗಿ ನಿತ್ಯ ಶಾಂತಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ ಮತ್ತು ಭಗವದ್ಭಕ್ತನು ಎಂದಿಗೂ ವಿನಾಶ ಹೊಂದುವುದಿಲ್ಲ'
}

abhinav_32_34 = {
    'hi': '।।9.32--9.34।। श्री अभिनवगुप्त कहते हैं: हे अर्जुन ! जो भी पापयोनि स्त्री, वैश्य, शूद्र आदि हों, वे भी मेरी अनन्य शरण लेकर परम गति को प्राप्त होते हैं; फिर पुण्यशील ब्राह्मणों और राजर्षियों का तो कहना ही क्या ! इसलिए इस अनित्य असुख संसार में आकर निरंतर मुझमें मन लगाकर मेरे अनन्य भक्त होकर मेरी ही शरण प्राप्त करो।',
    'en': '9.32--9.34 Sri Abhinavagupta states: O Arjuna! Taking exclusive refuge in Me, even women, Vaishyas, Shudras, and those of low origin attain the supreme goal; how much more then pious Brahmanas and royal sages! Therefore, having come into this impermanent joyless world, fix your mind on Me, become My exclusive devotee, and surrender unto Me alone.',
    'be': '৯.৩২--৯.৩৪ শ্রী অভিনবগুপ্ত বলেছেন: হে অর্জুন! যে কেউ পাপযোনি স্ত্রী, বৈশ্য, শূদ্র আদি হোক, তারাও আমার অনন্য শরণ নিয়ে পরম গতি প্রাপ্ত হয়; তবে পুণ্যশীল ব্রাহ্মণদের এবং রাজর্ষিদের তো কথাই কি ! তাই এই অনিত্য অসুখ সংসারে এসে নিরন্তর আমাতে মন লাগিয়ে আমার অনন্য ভক্ত হয়ে আমারই শরণ প্রাপ্ত হও।',
    'ka': '೯.೩೨--೯.೩೪ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಹೇ ಅರ್ಜುನ! ಯಾವ ಪಾಪಯೋನಿಯ ಸ್ತ್ರೀಯರು, ವೈಶ್ಯರು, ಶೂದ್ರರೇ ಇರಲಿ, ಅವರೂ ಸಹ ನನ್ನ ಅನನ್ಯ ಶರಣು ಹೊಂದಿ ಪರಮ ಗತಿಯನ್ನು ಪಡೆಯುತ್ತಾರೆ; ಇನ್ನು ಪುಣ್ಯಶಾಲಿಗಳಾದ ಬ್ರಾಹ್ಮಣರ ಹಾಗೂ ರಾಜರ್ಷಿಗಳ ಮಾತೇನು ! ಆದ್ದರಿಂದ ಈ ಅನಿತ್ಯವೂ ಅಸುಖಕರವೂ ಆದ ಸಂಸಾರಕ್ಕೆ ಬಂದು ನಿರಂತರವಾಗಿ ನನ್ನಲ್ಲಿ ಮನಸ್ಸನ್ನಿಟ್ಟು ನನ್ನ ಅನನ್ಯ ಭಕ್ತನಾಗಿ ನನ್ನನ್ನೇ ಶರಣು ಹೊಂದು'
}

